import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百零五章 入侵国土的大军","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/205第二百零五章 入侵国土的大军.md","filePath":"meditation/巴利文大藏经/205第二百零五章 入侵国土的大军.md"}'),r={name:"meditation/巴利文大藏经/205第二百零五章 入侵国土的大军.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百零五章-入侵国土的大军" tabindex="-1">第二百零五章 入侵国土的大军 <a class="header-anchor" href="#第二百零五章-入侵国土的大军" aria-label="Permalink to &quot;第二百零五章 入侵国土的大军&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部20相应8经/圆木头经(譬喻相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在毘舍离大林重阁讲堂，有一天，佛陀对出家弟子们说：“弟子们，现在离车族人他们用木块作为睡觉的枕头，他们的卧床也非常的简陋，他们每天很早就会起床训练武艺，并专心认真的完成每天的任务，他们不会放纵自己的行为，他们不会沉浸在各种欲望的海洋之中，这样摩揭陀国的阿闍世王就找不到入侵离车族人国家的机会，阿闍世王看见离车族人每天都如此努力奋进的训练武艺，每天都如此的遵守军令，他会担心自己的军队是否是离车族人军队的对手。阿闍世王看见离车族人不贪求各种舒适的生活，不会沉浸在各种欲望之中，他就会担心无法贿赂培植离车族中贪图富贵的反叛者。如此阿闍世王在多种顾虑之下，就不敢对离车族人的国家用兵，不敢入侵离车族人的国土。</p><p>弟子们，未来，离车族人，他们不会再用木块做枕头，他们将会用包裹着羽毛、毛绒的布袋做枕头，他们的卧床非常的柔软，他们盖的被子也非常的讲究。太阳高高升起的时候，他们都还赖在床上不起来。他们已经不会再在早上训练武艺了，他们的手脚纤细、娇嫩、白皙。他们的身体弱不禁风，握不稳刀剑武器，他们军纪涣散、吃喝玩乐。这时，摩揭陀国的阿闍世王就找到了入侵离车族人国家的机会，阿闍世王看见离车族人荒废武艺、军纪涣散，就知道他的军队一定能够打败离车族人的军队，他看见离车族人贪求各种舒适的生活，沉浸在各种欲望之中，他就知道可以贿赂培植离车族中贪图富贵的反叛者。如此阿闍世王就会毫无顾虑，他会率领大军入侵离车族人的国土，占领离车族人的城池，砍杀离车族人的武士，奴役离车族人的民众，将离车族人的国土并入他的国土之中。</p><p>弟子们，同样的道理，现在的修行人、出家人，他们用木块作为睡觉用的枕头，他们的卧床也非常的简陋，他们每天很早就会起床精进的修行，他们能够管束好自己的行为、言语、念想。他们不会身体行为做恶事，不会口说恶言，不会内心生起恶念，他们不会让自己胡思乱想、胡作非为，他们会让自己安住在清净的境界之中，这样魔王波旬就找不到引诱、控制、奴役、折磨他们的机会。魔王波旬是什么呢？魔王波旬就是内心中生起的各种欲望，也就是说这些欲望就无法束缚捆绑这些修行人、出家人。</p><p>未来的修行人、出家人，他们不会用木块作为睡觉用的枕头，他们将会用包裹着羽毛、毛绒的布袋做枕头，他们的卧床非常的柔软，他们盖的被子也非常的讲究。太阳高高升起的时候，他们都还赖在床上不起来。他们已经不会再精进的修行如来的正法了，他们的手脚纤细、娇嫩、白皙。他们的身体弱不禁风，走几步路都会喘气。他们不受持戒律、吃喝玩乐。这时，魔王波旬就找到了引诱、控制、奴役、折磨他们的机会，魔王波旬是什么呢？魔王波旬就是内心中生起的各种欲望，这些欲望就能束缚捆绑这些修行人、出家人。</p><p>弟子们，因此，你们应该这样去修行：「我们要用木块作为枕头，我们不要贪求舒适的生活，我们要管束好自己的行为、言语、念想。我们要让身体行为做善事，口说善言，内心生起善念，我们要让身体行为不做恶事，不说恶言，内心不生起恶念，我们不要胡思乱想、胡作非为，我们要将自己安住在清净的境界之中，我们要按如来的正法持之以恒、精进努力的去修行。」弟子们，你们就应该这样去修行。</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
